  ('c6fdb156-a92a-47fa-81d4-522ab14cf0a1', '25 インプレス ドライブスター TYPE／S ドライバー', 'ヤマハ', 'yamaha', 'inpres-drivestar-type-s-driver-2025', 'driver', '8軸カーボンフェース搭載 高初速＋正統派形状つかまり過ぎをおさえて飛ばす（発売：2024年9月20日（金））', 'フェース部分 カーボンフェース ボディ部分 811チタン精密鋳造ボディ、 カーボンクラウン、 ステンレスウェイト', NULL, 97900, NULL, NULL, 2024, 9, ARRAY['SPEEDER NX for Yamaha M-425D']::text[], '精密鋳造ボディ', '適合', 'https://golfnavi.info/club-cate/cate-driver/inpres-drivestar-type-s-driver-2025.php', NULL, NULL),
  ('4010937f-31cc-4df7-bcad-e48e421d0e7a', '25 インプレス ドライブスター フェアウェイウッド', 'ヤマハ', 'yamaha', 'inpres-drivestar-fairwaywood-2025', 'fairway_wood', 'X37×カーボンクラウン 高初速＋高弾道FW（発売：2024年9月20日（金））', 'ボディ部分 X37精密鋳造ボディ、 カーボンクラウン', NULL, 60500, NULL, NULL, 2024, 9, ARRAY['SPEEDER NX for Yamaha M-425F']::text[], '精密鋳造ボディ', NULL, 'https://golfnavi.info/club-cate/cate-fairwaywood/inpres-drivestar-fairwaywood-2025.php', NULL, NULL),
